  "criteria": {
    "c01_overall_legal_correctness": {
      "label": "not_met",
      "reason": "Svaret gengiver korrekt udløsergrundene og dækker de fire eksempler. Men det udelader forbeholdet 'i særlige tilfælde' og præsenterer de fem situationer som en samlet liste over, hvornår UDK kan bede om erklæringen. Det gør eksemplerne ('f.eks.') til en tilsyneladende udtømmende opregning. Det er en af rubrikkens væsentlige fejl."
    },
    "c02_required_elements_complete": {
      "label": "not_met",
      "reason": "De fire eksempelgrupper og art/grad-grunden er med. Det første kritiske element kræver dog, at det er 'i særlige tilfælde', og det udtrykkes ikke."
    },
    "c03_direct_relevance": {
      "label": "met",
      "reason": "Svaret besvarer direkte, hvornår UDK kan bede om en speciallægeerklæring, uden irrelevant tekst."
    },
    "c04_source_traceability": {
      "label": "not_met",
      "reason": "Svaret angiver ingen identificerbar kilde som bestemmelse, vejledning eller afsnit."
    },
    "c05_source_validity": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så gyldigheden kan ikke vurderes."
    },
    "c06_claim_source_support": {
      "label": "not_assessable",
      "reason": "Der er ikke angivet nogen kilde, så støtten kan ikke vurderes."
    },
    "c07_no_unsupported_legal_additions": {
      "label": "met",
      "reason": "Indholdet svarer til vejledningens afsnit 5.1.3.2. Svaret tilføjer ingen ny regel, betingelse eller myndighed, der ikke er understøttet."
    },
    "c08_qualifications_and_exceptions": {
      "label": "not_met",
      "reason": "'I særlige tilfælde' mangler. Svaret markerer heller ikke, at eksemplerne er illustrative ('f.eks.') og alternative, og at erklæringen ikke følger automatisk. 'Stor tvivl' er bevaret."
    },
    "c09_reasoning_coherence": {
      "label": "met",
      "reason": "Svaret er internt sammenhængende, og slutningen følger af de oplistede situationer."
    },
    "c10_legal_modality_precision": {
      "label": "not_met",
      "reason": "Svaret bruger 'kan', hvilket er rigtigt. Men det gør de illustrative eksempler til en fast liste over situationer og udelader 'i særlige tilfælde'. Dermed bliver skønnet og undtagelsen mere absolut end i kilden."
    }
  },
  "xhaile_coverage": {
    "A74": {
      "label": "partial",
      "reason": "Svaret dækker art/grad-grunden og alle fire eksempler. Det udelader 'i særlige tilfælde' og eksempelkarakteren ('f.eks.')."
    }
  },
  "overall_notes": "Indholdet er stort set korrekt og komplet for eksemplerne. Svaret mangler dog forbeholdet 'i særlige tilfælde', fremstiller eksemplerne som en afsluttet liste og angiver ingen kilder. Det angiver heller ikke, at UDK betaler udgifterne, men det er kun et supporting element."
}

